package main

import (
	"fmt"
	"time"
)

func generateReceiveLog(msg string) string {
	return "[" + time.Now().Format(time.RFC3339) + "] Received: " + msg
}

func main() {
	testMsg := "Hello, world!"
	logEntry := generateReceiveLog(testMsg)
	fmt.Println(logEntry)
}
